import AppKit

/// 두 서비스의 공식 파비콘(SVG)을 64x64 실루엣 PNG로 렌더링해 넣어 둔 것.
/// 알파 채널만 쓰는 템플릿 이미지라 라이트/다크 메뉴바에 자동으로 맞고,
/// 오버레이에서는 원하는 색으로 칠해 쓴다. 외부 리소스 의존이 없다.
enum Icons {
    static let claude = decode(claudeBase64)
    static let codex = decode(codexBase64)

    private static func decode(_ base64: String) -> NSImage {
        guard let data = Data(base64Encoded: base64), let image = NSImage(data: data) else {
            return NSImage(size: NSSize(width: 64, height: 64))
        }
        image.isTemplate = true
        return image
    }

    private static let claudeBase64 = ""

    private static let codexBase64 = ""
}
